using UnityEngine;

namespace _Project.Features.Boss.Scripts
{
    /// <summary>
    /// 공통 로직을 넣을 수 있는 보스 상태 베이스 클래스
    /// </summary>
    public abstract class BossStateBase : IBossState
    {
        protected readonly BossStateMachine stateMachine;

        protected BossStateBase(BossStateMachine stateMachine)
        {
            this.stateMachine = stateMachine;
        }

        public virtual void OnEnter() { }
        public virtual void OnExit() { }
        public virtual void Tick() { }
        public virtual void FixedTick() { }
    }
}

namespace _Project.Features.Boss.Scripts
{
    public interface IBossState
    {
        void OnEnter();
        void OnExit();
        void Tick();
        void FixedTick();
    }
}

using _Project.Features.Boss.Scripts;
using _Project.Features.Maehwa.Scripts.State;
using Boss.MaeHwa;
using UnityEngine;
using UnityEngine.Serialization;

namespace _Project.Features.Maehwa.Scripts
{
    public class MaehwaContext : BossContext<MaehwaStateId>
    {
        [SerializeField] public MaeHwaStats stats;

        public override void SetLookingDir(LookingDir dir)
        {
            base.SetLookingDir(dir);
            var atk = Attack as MaehwaAttack;
            if (atk != null)
                atk.SetAttackColliderDir(dir);
        }

        /// <summary>
        /// 플레이어와 보스 간의 거리와 좌우 위치를 기반으로 이동할 방향을 선택합니다.
        /// 가까우면 플레이어의 반대 방향, 멀면 플레이어가 있는 방향으로 이동하도록 합니다.
        /// </summary>
        /// <returns> true : 오른쪽으로 이동, false : 왼쪽으로 이동 </returns>
        public bool SelectMoveDir()
        {
            var isNear = IsInDistance(0f, stats.walkCloselyDistance);
            var playerOnRight = PlayerTransform.position.x > transform.position.x;

            if (isNear)
                return !playerOnRight;
            else
                return playerOnRight;
        }
        /// <summary>
        /// 
        /// </summary>
        /// <returns></returns>
        public ComboSelectDash.DashDir SelectDashDir()
        {
            var isNear = IsInDistance(0f, stats.comboAttackWithDashDistance);
            var playerOnRight = PlayerTransform.position.x > transform.position.x;

            if (isNear)
                return ComboSelectDash.DashDir.None;
            else
                return playerOnRight ? ComboSelectDash.DashDir.Right : ComboSelectDash.DashDir.Left;
        }

        public bool IsInDistance(float minDistance, float maxDistance)
        {
            var distance = Mathf.Abs(transform.position.x - PlayerTransform.position.x);
            return distance >= minDistance && distance <= maxDistance;
        }
    }
}

using _Project.Features.Boss.Scripts;
using _Project.Features.Maehwa.Scripts.State;
using Boss.MaeHwa;
using UnityEngine;
using UnityEngine.Serialization;

namespace _Project.Features.Maehwa.Scripts
{
    public class MaehwaContext : BossContext<MaehwaStateId>
    {
        [SerializeField] public MaeHwaStats stats;

        public ComboSelectDash.DashDir SelectedDashDir { get; set; } = ComboSelectDash.DashDir.None;

        public override void SetLookingDir(LookingDir dir)
        {
            base.SetLookingDir(dir);
            var atk = Attack as MaehwaAttack;
            if (atk != null)
                atk.SetAttackColliderDir(dir);
        }

        /// <summary>
        /// 플레이어와 보스 간의 거리와 좌우 위치를 기반으로 이동할 방향을 선택합니다.
        /// 가까우면 플레이어의 반대 방향, 멀면 플레이어가 있는 방향으로 이동하도록 합니다.
        /// </summary>
        /// <returns> true : 오른쪽으로 이동, false : 왼쪽으로 이동 </returns>
        public bool SelectMoveDir()
        {
            var isNear = IsInDistance(0f, stats.walkCloselyDistance);
            var playerOnRight = PlayerTransform.position.x > transform.position.x;

            if (isNear)
                return !playerOnRight;
            else
                return playerOnRight;
        }
        /// <summary>
        /// 
        /// </summary>
        /// <returns></returns>
        public ComboSelectDash.DashDir SelectDashDir()
        {
            var isNear = IsInDistance(0f, stats.comboAttackWithDashDistance);
            var playerOnRight = PlayerTransform.position.x > transform.position.x;

            if (isNear)
                return ComboSelectDash.DashDir.None;
            else
                return playerOnRight ? ComboSelectDash.DashDir.Right : ComboSelectDash.DashDir.Left;
        }
        
        public bool IsInDistance(float minDistance, float maxDistance)
        {
            var distance = Mathf.Abs(transform.position.x - PlayerTransform.position.x);
            return distance >= minDistance && distance <= maxDistance;
        }
    }
}

using _Project.Features.Boss.Scripts;
using _Project.Features.Boss.Scripts.State;
using _Project.Features.Boss.Scripts.State.Dead;
using _Project.Features.Boss.Scripts.State.Moving;
using _Project.Features.Maehwa.Scripts.State;
using Boss.MaeHwa;
using UnityEngine;

namespace _Project.Features.Maehwa.Scripts
{
    public class MaehwaStateMachine : BossStateMachine<MaehwaStateId, MaehwaContext>
    {
        public override void Initialize()
        {
            Context = GetComponent<MaehwaContext>();
            base.Initialize();

            var s = Context.stats;
            var atk = Context.Attack as MaehwaAttack;

            if (atk == null)
            {
                Debug.LogError("MaehwaStateMachine: MaehwaAttack 컴포넌트를 찾지 못했습니다.");
                return;
            }

            // 시작 대기 상태
            var startWait = new WaitState<MaehwaStateId>(MaehwaStateId.StartWait, s.startWaitTime, false);
            StateMachine.AddState(MaehwaStateId.StartWait, startWait);
            StateMachine.SetInitialState(MaehwaStateId.StartWait);

            // 사망 상태
            var deadState = new DeadNormal<MaehwaStateId>(MaehwaStateId.Dead);
            StateMachine.AddState(MaehwaStateId.Dead, deadState);
            StateMachine.AddAnyTransition(MaehwaStateId.Dead, ctx => ctx.IsDead());

            // Select-Pattern
            var selectPattern = new EmptyState<MaehwaStateId>(MaehwaStateId.SelectPattern);
            StateMachine.AddState(MaehwaStateId.SelectPattern, selectPattern);
            StateMachine.AddTransition(MaehwaStateId.StartWait, MaehwaStateId.SelectPattern, _ => startWait.IsFinished);

            // Select-Walk
            var selectWalk = new EmptyState<MaehwaStateId>(MaehwaStateId.SelectWalk);
            StateMachine.AddState(MaehwaStateId.SelectWalk, selectWalk);

            var walkLeft = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.WalkLeft, Vector2.left, s.walkSpeed, s.walkTime, 0f);
            var walkRight = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.WalkRight, Vector2.right, s.walkSpeed, s.walkTime, 0f);
            StateMachine.AddState(MaehwaStateId.WalkLeft, walkLeft);
            StateMachine.AddState(MaehwaStateId.WalkRight, walkRight);

            // Select-Step
            var selectStep = new EmptyState<MaehwaStateId>(MaehwaStateId.SelectStep);
            StateMachine.AddState(MaehwaStateId.SelectStep, selectStep);

            var frontStep = new Step<MaehwaStateId>(MaehwaStateId.FrontStep, Vector2.right * 3f, 20f, 10, 0.3f);
            var backStep = new Step<MaehwaStateId>(MaehwaStateId.BackStep, Vector2.right * 3f, 20f, 10, 0.3f);
            StateMachine.AddState(MaehwaStateId.FrontStep, frontStep);
            StateMachine.AddState(MaehwaStateId.BackStep, backStep);

            // Select-Attack
            var selectAttack = new EmptyState<MaehwaStateId>(MaehwaStateId.SelectAttack);
            StateMachine.AddState(MaehwaStateId.SelectAttack, selectAttack);

            // 패턴 선택 전이
            StateMachine.AddTransition(MaehwaStateId.SelectPattern, MaehwaStateId.SelectWalk, _ => true);
            StateMachine.AddTransition(MaehwaStateId.SelectPattern, MaehwaStateId.SelectStep, ctx => ctx.IsInDistance(0f, 2f), 0, 2f);
            StateMachine.AddTransition(MaehwaStateId.SelectPattern, MaehwaStateId.SelectAttack, _ => true);

            // Select-Walk -> WalkLeft / WalkRight
            StateMachine.AddTransition(MaehwaStateId.SelectWalk, MaehwaStateId.WalkRight, ctx => ctx.SelectMoveDir());
            StateMachine.AddTransition(MaehwaStateId.SelectWalk, MaehwaStateId.WalkLeft, ctx => !ctx.SelectMoveDir());

            // Walk 종료 후 Select-Attack
            StateMachine.AddTransition(MaehwaStateId.WalkLeft, MaehwaStateId.SelectAttack, _ => walkLeft.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.WalkRight, MaehwaStateId.SelectAttack, _ => walkRight.IsFinished);

            // Select-Step -> Front / Back
            StateMachine.AddTransition(MaehwaStateId.SelectStep, MaehwaStateId.BackStep, ctx => ctx.IsInDistance(0f, 3f));
            StateMachine.AddTransition(MaehwaStateId.SelectStep, MaehwaStateId.FrontStep, ctx => !ctx.IsInDistance(0f, 3f));

            // Step 종료 후 Select-Attack
            StateMachine.AddTransition(MaehwaStateId.FrontStep, MaehwaStateId.SelectAttack, _ => frontStep.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.BackStep, MaehwaStateId.SelectAttack, _ => backStep.IsFinished);

            // === Horizon / EndPhase ===
            var horizonBeforeWait = new WaitState<MaehwaStateId>(MaehwaStateId.HorizonBeforeWait, s.horizonBeforeWaitTime, true);
            var horizonAttack = new AttackFixedRange<MaehwaStateId>(MaehwaStateId.HorizonAttack, atk.HorizonAttackRange);
            var horizonAfterWait = new WaitState<MaehwaStateId>(MaehwaStateId.HorizonAfterWait, s.horizonAfterWaitTime, true);

            StateMachine.AddState(MaehwaStateId.HorizonBeforeWait, horizonBeforeWait);
            StateMachine.AddState(MaehwaStateId.HorizonAttack, horizonAttack);
            StateMachine.AddState(MaehwaStateId.HorizonAfterWait, horizonAfterWait);

            var endPhase = new WaitState<MaehwaStateId>(MaehwaStateId.EndPhase, s.betweenPhaseWaitTime, true);
            StateMachine.AddState(MaehwaStateId.EndPhase, endPhase);

            var horizonStart = new EmptyState<MaehwaStateId>(MaehwaStateId.HorizonStart);
            StateMachine.AddState(MaehwaStateId.HorizonStart, horizonStart);

            var horizonStep = new MoveByVelocityToPos<MaehwaStateId>(MaehwaStateId.HorizonStep, Vector2.right, s.horizonStepSpeed, 10f, Vector2.zero, 0f);
            StateMachine.AddState(MaehwaStateId.HorizonStep, horizonStep);

            StateMachine.AddTransition(MaehwaStateId.HorizonStart, MaehwaStateId.HorizonStep, _ => true);
            StateMachine.AddTransition(MaehwaStateId.HorizonStep, MaehwaStateId.HorizonBeforeWait, _ => true);
            StateMachine.AddTransition(MaehwaStateId.HorizonBeforeWait, MaehwaStateId.HorizonAttack, _ => horizonBeforeWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.HorizonAttack, MaehwaStateId.HorizonAfterWait, _ => true);
            StateMachine.AddTransition(MaehwaStateId.HorizonAfterWait, MaehwaStateId.EndPhase, _ => true);
            StateMachine.AddTransition(MaehwaStateId.EndPhase, MaehwaStateId.SelectPattern, _ => endPhase.IsFinished);

            // === Body ===
            var bodyAfterDashWait = new WaitState<MaehwaStateId>(MaehwaStateId.BodyAfterDashWait, s.bodyAfterDashWaitTime, false);
            var bodyLeftDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.BodyDash, Vector2.left, s.bodyDashSpeed, s.bodyDashTime, 0f);
            var bodyRightDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.BodyDash, Vector2.right, s.bodyDashSpeed, s.bodyDashTime, 0f);
            var bodyAttack = new AttackFixedRange<MaehwaStateId>(MaehwaStateId.BodyAttack, atk.BodyStrongAttack);
            var bodyAfterAttackWait = new WaitState<MaehwaStateId>(MaehwaStateId.BodyAfterAttackWait, s.bodyAfterAttackWaitTime, false);

            var bodyStart = new EmptyState<MaehwaStateId>(MaehwaStateId.BodyStart);
            StateMachine.AddState(MaehwaStateId.BodyStart, bodyStart);
            StateMachine.AddState(MaehwaStateId.BodyAfterDashWait, bodyAfterDashWait);
            StateMachine.AddState(MaehwaStateId.BodyDash, bodyLeftDash);
            StateMachine.AddState(MaehwaStateId.BodyAttack, bodyAttack);
            StateMachine.AddState(MaehwaStateId.BodyAfterAttackWait, bodyAfterAttackWait);

            StateMachine.AddTransition(MaehwaStateId.BodyStart, MaehwaStateId.BodyDash, _ => true);
            StateMachine.AddTransition(MaehwaStateId.BodyDash, MaehwaStateId.BodyAfterDashWait, _ => bodyLeftDash.IsFinished || bodyRightDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.BodyAfterDashWait, MaehwaStateId.BodyAttack, _ => bodyAfterDashWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.BodyAttack, MaehwaStateId.BodyAfterAttackWait, _ => true);
            StateMachine.AddTransition(MaehwaStateId.BodyAfterAttackWait, MaehwaStateId.EndPhase, _ => true);

            // === Combo ===
            var comboStart = new EmptyState<MaehwaStateId>(MaehwaStateId.ComboStart);

            var comboFirstBeforeWait = new ComboSelectDash(MaehwaStateId.ComboFirstBeforeWait, s.comboFirstBeforeWaitTime);
            // 통합 콤보 공격 상태: First
            var comboFirstAttack = new ComboAttackState(
                MaehwaStateId.ComboFirstAttackColliderActive,
                Vector2.zero,                // 대시 없음 기본값, 실제 대시는 이후 상태에서 처리하거나 필요시 확장
                s.comboNormalSpeed,
                s.comboNormalLength,
                s.comboNormalLength,
                ComboAttackState.BossAttackRangeType.ComboNormal);
            var comboFirstNoDash = new WaitState<MaehwaStateId>(MaehwaStateId.ComboFirstAttackingWait, s.comboNormalLength, false);
            var comboFirstLeftDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboFirstAttackingLeftDash, Vector2.left, s.comboNormalSpeed, s.comboNormalLength, 0f);
            var comboFirstRightDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboFirstAttackingRightDash, Vector2.right, s.comboNormalSpeed, s.comboNormalLength, 0f);
            var comboFirstAfterWait = new WaitState<MaehwaStateId>(MaehwaStateId.ComboFirstAfterWait, s.comboAfterFirstWaitTime, false);

            var comboSecondBeforeWait = new ComboSelectDash(MaehwaStateId.ComboSecondBeforeWait, s.comboBeforeSecondWaitTime, false);
            // 통합 콤보 공격 상태: Second
            var comboSecondAttack = new ComboAttackState(
                MaehwaStateId.ComboSecondAttackColliderActive,
                Vector2.zero,
                s.comboNormalSpeed,
                s.comboNormalLength,
                s.comboNormalLength,
                ComboAttackState.BossAttackRangeType.ComboNormal);
            var comboSecondNoDash = new WaitState<MaehwaStateId>(MaehwaStateId.ComboSecondAttackingWait, s.comboNormalLength, false);
            var comboSecondLeftDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboSecondAttackingLeftDash, Vector2.left, s.comboNormalSpeed, s.comboNormalLength, 0f);
            var comboSecondRightDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboSecondAttackingRightDash, Vector2.right, s.comboNormalSpeed, s.comboNormalLength, 0f);
            var comboSecondAfterWait = new WaitState<MaehwaStateId>(MaehwaStateId.ComboSecondAfterWait, s.comboAfterSecondWaitTime, false);

            var comboThirdBeforeWait = new ComboSelectDash(MaehwaStateId.ComboThirdBeforeWait, s.comboBeforeThirdWaitTime, false, true);
            // 통합 콤보 공격 상태: Third (Sting)
            var comboThirdAttack = new ComboAttackState(
                MaehwaStateId.ComboThirdAttackColliderActive,
                Vector2.zero,
                s.comboStingSpeed,
                s.comboStingTime,
                s.comboStingTime,
                ComboAttackState.BossAttackRangeType.ComboSting);
            var comboThirdLeftDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboThirdAttackingDashLeft, Vector2.left, s.comboStingSpeed, s.comboStingTime, 0f);
            var comboThirdRightDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboThirdAttackingDashRight, Vector2.right, s.comboStingSpeed, s.comboStingTime, 0f);
            var comboThirdAfterWait = new WaitState<MaehwaStateId>(MaehwaStateId.ComboAfterWait, s.comboAfterThirdWaitTime, false);

            StateMachine.AddState(MaehwaStateId.ComboStart, comboStart);

            StateMachine.AddState(MaehwaStateId.ComboFirstBeforeWait, comboFirstBeforeWait);
            StateMachine.AddState(MaehwaStateId.ComboFirstAttackColliderActive, comboFirstAttack);
            StateMachine.AddState(MaehwaStateId.ComboFirstAttackingWait, comboFirstNoDash);
            StateMachine.AddState(MaehwaStateId.ComboFirstAttackingLeftDash, comboFirstLeftDash);
            StateMachine.AddState(MaehwaStateId.ComboFirstAttackingRightDash, comboFirstRightDash);
            StateMachine.AddState(MaehwaStateId.ComboFirstAfterWait, comboFirstAfterWait);

            StateMachine.AddState(MaehwaStateId.ComboSecondBeforeWait, comboSecondBeforeWait);
            StateMachine.AddState(MaehwaStateId.ComboSecondAttackColliderActive, comboSecondAttack);
            StateMachine.AddState(MaehwaStateId.ComboSecondAttackingWait, comboSecondNoDash);
            StateMachine.AddState(MaehwaStateId.ComboSecondAttackingLeftDash, comboSecondLeftDash);
            StateMachine.AddState(MaehwaStateId.ComboSecondAttackingRightDash, comboSecondRightDash);
            StateMachine.AddState(MaehwaStateId.ComboSecondAfterWait, comboSecondAfterWait);

            StateMachine.AddState(MaehwaStateId.ComboThirdBeforeWait, comboThirdBeforeWait);
            StateMachine.AddState(MaehwaStateId.ComboThirdAttackColliderActive, comboThirdAttack);
            StateMachine.AddState(MaehwaStateId.ComboThirdAttackingDashLeft, comboThirdLeftDash);
            StateMachine.AddState(MaehwaStateId.ComboThirdAttackingDashRight, comboThirdRightDash);
            StateMachine.AddState(MaehwaStateId.ComboAfterWait, comboThirdAfterWait);

            StateMachine.AddTransition(MaehwaStateId.ComboStart, MaehwaStateId.ComboFirstBeforeWait, _ => true);

            StateMachine.AddTransition(MaehwaStateId.ComboFirstBeforeWait, MaehwaStateId.ComboFirstAttackColliderActive, _ => comboFirstBeforeWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackColliderActive, MaehwaStateId.ComboFirstAttackingWait, _ => comboFirstBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.None);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackColliderActive, MaehwaStateId.ComboFirstAttackingLeftDash, _ => comboFirstBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.Left);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackColliderActive, MaehwaStateId.ComboFirstAttackingRightDash, _ => comboFirstBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.Right);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackingWait, MaehwaStateId.ComboFirstAfterWait, _ => comboFirstNoDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackingLeftDash, MaehwaStateId.ComboFirstAfterWait, _ => comboFirstLeftDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackingRightDash, MaehwaStateId.ComboFirstAfterWait, _ => comboFirstRightDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAfterWait, MaehwaStateId.ComboSecondBeforeWait, ctx => ctx.IsInDistance(0, s.comboSkipSecondDistance) && comboFirstAfterWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAfterWait, MaehwaStateId.ComboThirdBeforeWait, ctx => !ctx.IsInDistance(0, s.comboSkipSecondDistance) && comboFirstAfterWait.IsFinished);

            StateMachine.AddTransition(MaehwaStateId.ComboSecondBeforeWait, MaehwaStateId.ComboSecondAttackColliderActive, _ => comboSecondBeforeWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackColliderActive, MaehwaStateId.ComboSecondAttackingWait, _ => comboSecondBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.None);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackColliderActive, MaehwaStateId.ComboSecondAttackingLeftDash, _ => comboSecondBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.Left);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackColliderActive, MaehwaStateId.ComboSecondAttackingRightDash, _ => comboSecondBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.Right);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackingWait, MaehwaStateId.ComboSecondAfterWait, _ => comboSecondNoDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackingLeftDash, MaehwaStateId.ComboSecondAfterWait, _ => comboSecondLeftDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackingRightDash, MaehwaStateId.ComboSecondAfterWait, _ => comboSecondRightDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAfterWait, MaehwaStateId.ComboThirdBeforeWait, _ => comboSecondAfterWait.IsFinished);

            StateMachine.AddTransition(MaehwaStateId.ComboThirdBeforeWait, MaehwaStateId.ComboThirdAttackColliderActive, _ => comboThirdBeforeWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboThirdAttackColliderActive, MaehwaStateId.ComboThirdAttackingDashLeft, ctx => comboThirdBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.Left);
            StateMachine.AddTransition(MaehwaStateId.ComboThirdAttackColliderActive, MaehwaStateId.ComboThirdAttackingDashRight, ctx => comboThirdBeforeWait.SelectedDashDir != ComboSelectDash.DashDir.Left);
            StateMachine.AddTransition(MaehwaStateId.ComboThirdAttackingDashLeft, MaehwaStateId.ComboAfterWait, _ => comboThirdLeftDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboThirdAttackingDashRight, MaehwaStateId.ComboAfterWait, _ => comboThirdRightDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboAfterWait, MaehwaStateId.EndPhase, _ => comboThirdAfterWait.IsFinished);

            // === Rampage ===
            var rampageRise = new MoveLikeJump<MaehwaStateId>(MaehwaStateId.RampageRise, s.rampageRiseSpeed, s.rampageRiseTime);
            var rampageRiseWait = new WaitState<MaehwaStateId>(MaehwaStateId.RampageRiseWait, s.rampageRiseWaitTime, true);
            var rampageBeforeNoticeWait = new WaitState<MaehwaStateId>(MaehwaStateId.RampageBeforeNoticeWait, s.rampageBeforeNoticeWaitTime, true);
            var rampageBlink = new Teleport<MaehwaStateId>(MaehwaStateId.DownBlink, true, new Vector2(0, 7f), Context.PlayerTransform);
            var rampageNotice = new RampageAttackState(MaehwaStateId.RampageNotice, s.rampageNoticeInterval, s.rampageBeforeAttackTime, s.rampageAttackTime, s.rampageAttackAfterWaitTime);

            var rampageStart = new EmptyState<MaehwaStateId>(MaehwaStateId.RampageStart);
            StateMachine.AddState(MaehwaStateId.RampageStart, rampageStart);
            StateMachine.AddState(MaehwaStateId.RampageRise, rampageRise);
            StateMachine.AddState(MaehwaStateId.RampageRiseWait, rampageRiseWait);
            StateMachine.AddState(MaehwaStateId.RampageBeforeNoticeWait, rampageBeforeNoticeWait);
            StateMachine.AddState(MaehwaStateId.RampageBlink, rampageBlink);
            StateMachine.AddState(MaehwaStateId.RampageNotice, rampageNotice);

            StateMachine.AddTransition(MaehwaStateId.RampageStart, MaehwaStateId.RampageRise, _ => true);
            StateMachine.AddTransition(MaehwaStateId.RampageRise, MaehwaStateId.RampageRiseWait, _ => rampageRise.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.RampageRiseWait, MaehwaStateId.RampageBeforeNoticeWait, _ => rampageRiseWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.RampageBeforeNoticeWait, MaehwaStateId.RampageNotice, _ => rampageBeforeNoticeWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.RampageNotice, MaehwaStateId.DownAirWait, _ => true);

            // === Down ===
            var downBlink = new Teleport<MaehwaStateId>(MaehwaStateId.DownBlink, true, new Vector2(0, 7f), Context.PlayerTransform);
            var downAirWait = new WaitState<MaehwaStateId>(MaehwaStateId.DownAirWait, s.downAirWaitTime, true);
            var downGetAccel = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.DownGetAccel, Vector2.down, s.downAccel, s.downAccelTime, 0f);
            var downSmashWait = new WaitState<MaehwaStateId>(MaehwaStateId.DownSmashWait, s.downAfterSmashTime, false);
            var downSmashRampageWait = new WaitState<MaehwaStateId>(MaehwaStateId.DownSmashRampageWait, s.rampageStaggerTime, false);

            var downStart = new EmptyState<MaehwaStateId>(MaehwaStateId.DownStart);
            StateMachine.AddState(MaehwaStateId.DownStart, downStart);
            StateMachine.AddState(MaehwaStateId.DownBlink, downBlink);
            StateMachine.AddState(MaehwaStateId.DownAirWait, downAirWait);
            StateMachine.AddState(MaehwaStateId.DownGetAccel, downGetAccel);
            StateMachine.AddState(MaehwaStateId.DownSmashWait, downSmashWait);
            StateMachine.AddState(MaehwaStateId.DownSmashRampageWait, downSmashRampageWait);

            StateMachine.AddTransition(MaehwaStateId.DownStart, MaehwaStateId.DownBlink, _ => true);
            StateMachine.AddTransition(MaehwaStateId.DownBlink, MaehwaStateId.DownAirWait, _ => true);
            StateMachine.AddTransition(MaehwaStateId.DownAirWait, MaehwaStateId.DownGetAccel, _ => downAirWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.DownGetAccel, MaehwaStateId.DownSmashWait, ctx => ctx.IsOnPlatform());
            StateMachine.AddTransition(MaehwaStateId.DownSmashWait, MaehwaStateId.EndPhase, _ => true);
            StateMachine.AddTransition(MaehwaStateId.DownSmashRampageWait, MaehwaStateId.EndPhase, _ => true);

            // Select-Attack 에서 패턴 분기
            StateMachine.AddTransition(MaehwaStateId.SelectAttack, MaehwaStateId.ComboStart, _ => true);
            // StateMachine.AddTransition(MaehwaStateId.SelectAttack, MaehwaStateId.BodyStart, _ => true);
            // StateMachine.AddTransition(MaehwaStateId.SelectAttack, MaehwaStateId.HorizonStart, _ => true);
            // StateMachine.AddTransition(MaehwaStateId.SelectAttack, MaehwaStateId.RampageStart, _ => true);
            // StateMachine.AddTransition(MaehwaStateId.SelectAttack, MaehwaStateId.DownStart, _ => true);
        }
    }
}

using _Project.Features.Boss.Scripts;
using _Project.Features.Boss.Scripts.State;
using _Project.Features.Boss.Scripts.State.Dead;
using _Project.Features.Boss.Scripts.State.Moving;
using _Project.Features.Maehwa.Scripts.State;
using Boss.MaeHwa;
using UnityEngine;

namespace _Project.Features.Maehwa.Scripts
{
    public class MaehwaStateMachine : BossStateMachine<MaehwaStateId, MaehwaContext>
    {
        public override void Initialize()
        {
            Context = GetComponent<MaehwaContext>();
            base.Initialize();

            var s = Context.stats;
            var atk = Context.Attack as MaehwaAttack;

            if (atk == null)
            {
                Debug.LogError("MaehwaStateMachine: MaehwaAttack 컴포넌트를 찾지 못했습니다.");
                return;
            }

            // 시작 대기 상태
            var startWait = new WaitState<MaehwaStateId>(MaehwaStateId.StartWait, s.startWaitTime, false);
            StateMachine.AddState(MaehwaStateId.StartWait, startWait);
            StateMachine.SetInitialState(MaehwaStateId.StartWait);

            // 사망 상태
            var deadState = new DeadNormal<MaehwaStateId>(MaehwaStateId.Dead);
            StateMachine.AddState(MaehwaStateId.Dead, deadState);
            StateMachine.AddAnyTransition(MaehwaStateId.Dead, ctx => ctx.IsDead());

            // Select-Pattern
            var selectPattern = new EmptyState<MaehwaStateId>(MaehwaStateId.SelectPattern);
            StateMachine.AddState(MaehwaStateId.SelectPattern, selectPattern);
            StateMachine.AddTransition(MaehwaStateId.StartWait, MaehwaStateId.SelectPattern, _ => startWait.IsFinished);

            // Select-Walk
            var selectWalk = new EmptyState<MaehwaStateId>(MaehwaStateId.SelectWalk);
            StateMachine.AddState(MaehwaStateId.SelectWalk, selectWalk);

            var walkLeft = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.WalkLeft, Vector2.left, s.walkSpeed, s.walkTime, 0f);
            var walkRight = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.WalkRight, Vector2.right, s.walkSpeed, s.walkTime, 0f);
            StateMachine.AddState(MaehwaStateId.WalkLeft, walkLeft);
            StateMachine.AddState(MaehwaStateId.WalkRight, walkRight);

            // Select-Step
            var selectStep = new EmptyState<MaehwaStateId>(MaehwaStateId.SelectStep);
            StateMachine.AddState(MaehwaStateId.SelectStep, selectStep);

            var frontStep = new Step<MaehwaStateId>(MaehwaStateId.FrontStep, Vector2.right * 3f, 20f, 10, 0.3f);
            var backStep = new Step<MaehwaStateId>(MaehwaStateId.BackStep, Vector2.right * 3f, 20f, 10, 0.3f);
            StateMachine.AddState(MaehwaStateId.FrontStep, frontStep);
            StateMachine.AddState(MaehwaStateId.BackStep, backStep);

            // Select-Attack
            var selectAttack = new EmptyState<MaehwaStateId>(MaehwaStateId.SelectAttack);
            StateMachine.AddState(MaehwaStateId.SelectAttack, selectAttack);

            // 패턴 선택 전이
            StateMachine.AddTransition(MaehwaStateId.SelectPattern, MaehwaStateId.SelectWalk, _ => true);
            StateMachine.AddTransition(MaehwaStateId.SelectPattern, MaehwaStateId.SelectStep, ctx => ctx.IsInDistance(0f, 2f), 0, 2f);
            StateMachine.AddTransition(MaehwaStateId.SelectPattern, MaehwaStateId.SelectAttack, _ => true);

            // Select-Walk -> WalkLeft / WalkRight
            StateMachine.AddTransition(MaehwaStateId.SelectWalk, MaehwaStateId.WalkRight, ctx => ctx.SelectMoveDir());
            StateMachine.AddTransition(MaehwaStateId.SelectWalk, MaehwaStateId.WalkLeft, ctx => !ctx.SelectMoveDir());

            // Walk 종료 후 Select-Attack
            StateMachine.AddTransition(MaehwaStateId.WalkLeft, MaehwaStateId.SelectAttack, _ => walkLeft.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.WalkRight, MaehwaStateId.SelectAttack, _ => walkRight.IsFinished);

            // Select-Step -> Front / Back
            StateMachine.AddTransition(MaehwaStateId.SelectStep, MaehwaStateId.BackStep, ctx => ctx.IsInDistance(0f, 3f));
            StateMachine.AddTransition(MaehwaStateId.SelectStep, MaehwaStateId.FrontStep, ctx => !ctx.IsInDistance(0f, 3f));

            // Step 종료 후 Select-Attack
            StateMachine.AddTransition(MaehwaStateId.FrontStep, MaehwaStateId.SelectAttack, _ => frontStep.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.BackStep, MaehwaStateId.SelectAttack, _ => backStep.IsFinished);

            // === Horizon / EndPhase ===
            var horizonBeforeWait = new WaitState<MaehwaStateId>(MaehwaStateId.HorizonBeforeWait, s.horizonBeforeWaitTime, true);
            var horizonAttack = new AttackFixedRange<MaehwaStateId>(MaehwaStateId.HorizonAttack, atk.HorizonAttackRange);
            var horizonAfterWait = new WaitState<MaehwaStateId>(MaehwaStateId.HorizonAfterWait, s.horizonAfterWaitTime, true);

            StateMachine.AddState(MaehwaStateId.HorizonBeforeWait, horizonBeforeWait);
            StateMachine.AddState(MaehwaStateId.HorizonAttack, horizonAttack);
            StateMachine.AddState(MaehwaStateId.HorizonAfterWait, horizonAfterWait);

            var endPhase = new WaitState<MaehwaStateId>(MaehwaStateId.EndPhase, s.betweenPhaseWaitTime, true);
            StateMachine.AddState(MaehwaStateId.EndPhase, endPhase);

            var horizonStart = new EmptyState<MaehwaStateId>(MaehwaStateId.HorizonStart);
            StateMachine.AddState(MaehwaStateId.HorizonStart, horizonStart);

            var horizonStep = new MoveByVelocityToPos<MaehwaStateId>(MaehwaStateId.HorizonStep, Vector2.right, s.horizonStepSpeed, 10f, Vector2.zero, 0f);
            StateMachine.AddState(MaehwaStateId.HorizonStep, horizonStep);

            StateMachine.AddTransition(MaehwaStateId.HorizonStart, MaehwaStateId.HorizonStep, _ => true);
            StateMachine.AddTransition(MaehwaStateId.HorizonStep, MaehwaStateId.HorizonBeforeWait, _ => true);
            StateMachine.AddTransition(MaehwaStateId.HorizonBeforeWait, MaehwaStateId.HorizonAttack, _ => horizonBeforeWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.HorizonAttack, MaehwaStateId.HorizonAfterWait, _ => true);
            StateMachine.AddTransition(MaehwaStateId.HorizonAfterWait, MaehwaStateId.EndPhase, _ => true);
            StateMachine.AddTransition(MaehwaStateId.EndPhase, MaehwaStateId.SelectPattern, _ => endPhase.IsFinished);

            // === Body ===
            var bodyAfterDashWait = new WaitState<MaehwaStateId>(MaehwaStateId.BodyAfterDashWait, s.bodyAfterDashWaitTime, false);
            var bodyLeftDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.BodyDash, Vector2.left, s.bodyDashSpeed, s.bodyDashTime, 0f);
            var bodyRightDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.BodyDash, Vector2.right, s.bodyDashSpeed, s.bodyDashTime, 0f);
            var bodyAttack = new AttackFixedRange<MaehwaStateId>(MaehwaStateId.BodyAttack, atk.BodyStrongAttack);
            var bodyAfterAttackWait = new WaitState<MaehwaStateId>(MaehwaStateId.BodyAfterAttackWait, s.bodyAfterAttackWaitTime, false);

            var bodyStart = new EmptyState<MaehwaStateId>(MaehwaStateId.BodyStart);
            StateMachine.AddState(MaehwaStateId.BodyStart, bodyStart);
            StateMachine.AddState(MaehwaStateId.BodyAfterDashWait, bodyAfterDashWait);
            StateMachine.AddState(MaehwaStateId.BodyDash, bodyLeftDash);
            StateMachine.AddState(MaehwaStateId.BodyAttack, bodyAttack);
            StateMachine.AddState(MaehwaStateId.BodyAfterAttackWait, bodyAfterAttackWait);

            StateMachine.AddTransition(MaehwaStateId.BodyStart, MaehwaStateId.BodyDash, _ => true);
            StateMachine.AddTransition(MaehwaStateId.BodyDash, MaehwaStateId.BodyAfterDashWait, _ => bodyLeftDash.IsFinished || bodyRightDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.BodyAfterDashWait, MaehwaStateId.BodyAttack, _ => bodyAfterDashWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.BodyAttack, MaehwaStateId.BodyAfterAttackWait, _ => true);
            StateMachine.AddTransition(MaehwaStateId.BodyAfterAttackWait, MaehwaStateId.EndPhase, _ => true);

            // === Combo ===
            var comboStart = new EmptyState<MaehwaStateId>(MaehwaStateId.ComboStart);

            var comboFirstBeforeWait = new ComboSelectDash(MaehwaStateId.ComboFirstBeforeWait, s.comboFirstBeforeWaitTime);
            // 통합 콤보 공격 상태: First
            var comboFirstAttack = new ComboAttackState(
                MaehwaStateId.ComboFirstAttackColliderActive,
                Vector2.zero,                // 대시 없음 기본값, 실제 대시는 이후 상태에서 처리하거나 필요시 확장
                s.comboNormalSpeed,
                s.comboNormalLength,
                s.comboNormalLength,
                ComboAttackState.BossAttackRangeType.ComboNormal);
            var comboFirstNoDash = new WaitState<MaehwaStateId>(MaehwaStateId.ComboFirstAttackingWait, s.comboNormalLength, false);
            var comboFirstLeftDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboFirstAttackingLeftDash, Vector2.left, s.comboNormalSpeed, s.comboNormalLength, 0f);
            var comboFirstRightDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboFirstAttackingRightDash, Vector2.right, s.comboNormalSpeed, s.comboNormalLength, 0f);
            var comboFirstAfterWait = new WaitState<MaehwaStateId>(MaehwaStateId.ComboFirstAfterWait, s.comboAfterFirstWaitTime, false);

            var comboSecondBeforeWait = new ComboSelectDash(MaehwaStateId.ComboSecondBeforeWait, s.comboBeforeSecondWaitTime, false);
            // 통합 콤보 공격 상태: Second
            var comboSecondAttack = new ComboAttackState(
                MaehwaStateId.ComboSecondAttackColliderActive,
                Vector2.zero,
                s.comboNormalSpeed,
                s.comboNormalLength,
                s.comboNormalLength,
                ComboAttackState.BossAttackRangeType.ComboNormal);
            var comboSecondNoDash = new WaitState<MaehwaStateId>(MaehwaStateId.ComboSecondAttackingWait, s.comboNormalLength, false);
            var comboSecondLeftDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboSecondAttackingLeftDash, Vector2.left, s.comboNormalSpeed, s.comboNormalLength, 0f);
            var comboSecondRightDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboSecondAttackingRightDash, Vector2.right, s.comboNormalSpeed, s.comboNormalLength, 0f);
            var comboSecondAfterWait = new WaitState<MaehwaStateId>(MaehwaStateId.ComboSecondAfterWait, s.comboAfterSecondWaitTime, false);

            var comboThirdBeforeWait = new ComboSelectDash(MaehwaStateId.ComboThirdBeforeWait, s.comboBeforeThirdWaitTime, false, true);
            // 통합 콤보 공격 상태: Third (Sting)
            var comboThirdAttack = new ComboAttackState(
                MaehwaStateId.ComboThirdAttackColliderActive,
                Vector2.zero,
                s.comboStingSpeed,
                s.comboStingTime,
                s.comboStingTime,
                ComboAttackState.BossAttackRangeType.ComboSting);
            var comboThirdLeftDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboThirdAttackingDashLeft, Vector2.left, s.comboStingSpeed, s.comboStingTime, 0f);
            var comboThirdRightDash = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.ComboThirdAttackingDashRight, Vector2.right, s.comboStingSpeed, s.comboStingTime, 0f);
            var comboThirdAfterWait = new WaitState<MaehwaStateId>(MaehwaStateId.ComboAfterWait, s.comboAfterThirdWaitTime, false);

            StateMachine.AddState(MaehwaStateId.ComboStart, comboStart);

            StateMachine.AddState(MaehwaStateId.ComboFirstBeforeWait, comboFirstBeforeWait);
            StateMachine.AddState(MaehwaStateId.ComboFirstAttackColliderActive, comboFirstAttack);
            StateMachine.AddState(MaehwaStateId.ComboFirstAttackingWait, comboFirstNoDash);
            StateMachine.AddState(MaehwaStateId.ComboFirstAttackingLeftDash, comboFirstLeftDash);
            StateMachine.AddState(MaehwaStateId.ComboFirstAttackingRightDash, comboFirstRightDash);
            StateMachine.AddState(MaehwaStateId.ComboFirstAfterWait, comboFirstAfterWait);

            StateMachine.AddState(MaehwaStateId.ComboSecondBeforeWait, comboSecondBeforeWait);
            StateMachine.AddState(MaehwaStateId.ComboSecondAttackColliderActive, comboSecondAttack);
            StateMachine.AddState(MaehwaStateId.ComboSecondAttackingWait, comboSecondNoDash);
            StateMachine.AddState(MaehwaStateId.ComboSecondAttackingLeftDash, comboSecondLeftDash);
            StateMachine.AddState(MaehwaStateId.ComboSecondAttackingRightDash, comboSecondRightDash);
            StateMachine.AddState(MaehwaStateId.ComboSecondAfterWait, comboSecondAfterWait);

            StateMachine.AddState(MaehwaStateId.ComboThirdBeforeWait, comboThirdBeforeWait);
            StateMachine.AddState(MaehwaStateId.ComboThirdAttackColliderActive, comboThirdAttack);
            StateMachine.AddState(MaehwaStateId.ComboThirdAttackingDashLeft, comboThirdLeftDash);
            StateMachine.AddState(MaehwaStateId.ComboThirdAttackingDashRight, comboThirdRightDash);
            StateMachine.AddState(MaehwaStateId.ComboAfterWait, comboThirdAfterWait);

            StateMachine.AddTransition(MaehwaStateId.ComboStart, MaehwaStateId.ComboFirstBeforeWait, _ => true);

            StateMachine.AddTransition(MaehwaStateId.ComboFirstBeforeWait, MaehwaStateId.ComboFirstAttackColliderActive, _ => comboFirstBeforeWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackColliderActive, MaehwaStateId.ComboFirstAttackingWait, _ => comboFirstBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.None);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackColliderActive, MaehwaStateId.ComboFirstAttackingLeftDash, _ => comboFirstBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.Left);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackColliderActive, MaehwaStateId.ComboFirstAttackingRightDash, _ => comboFirstBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.Right);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackingWait, MaehwaStateId.ComboFirstAfterWait, _ => comboFirstNoDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackingLeftDash, MaehwaStateId.ComboFirstAfterWait, _ => comboFirstLeftDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAttackingRightDash, MaehwaStateId.ComboFirstAfterWait, _ => comboFirstRightDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAfterWait, MaehwaStateId.ComboSecondBeforeWait, ctx => ctx.IsInDistance(0, s.comboSkipSecondDistance) && comboFirstAfterWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboFirstAfterWait, MaehwaStateId.ComboThirdBeforeWait, ctx => !ctx.IsInDistance(0, s.comboSkipSecondDistance) && comboFirstAfterWait.IsFinished);

            StateMachine.AddTransition(MaehwaStateId.ComboSecondBeforeWait, MaehwaStateId.ComboSecondAttackColliderActive, _ => comboSecondBeforeWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackColliderActive, MaehwaStateId.ComboSecondAttackingWait, _ => comboSecondBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.None);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackColliderActive, MaehwaStateId.ComboSecondAttackingLeftDash, _ => comboSecondBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.Left);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackColliderActive, MaehwaStateId.ComboSecondAttackingRightDash, _ => comboSecondBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.Right);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackingWait, MaehwaStateId.ComboSecondAfterWait, _ => comboSecondNoDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackingLeftDash, MaehwaStateId.ComboSecondAfterWait, _ => comboSecondLeftDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAttackingRightDash, MaehwaStateId.ComboSecondAfterWait, _ => comboSecondRightDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboSecondAfterWait, MaehwaStateId.ComboThirdBeforeWait, _ => comboSecondAfterWait.IsFinished);

            StateMachine.AddTransition(MaehwaStateId.ComboThirdBeforeWait, MaehwaStateId.ComboThirdAttackColliderActive, _ => comboThirdBeforeWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboThirdAttackColliderActive, MaehwaStateId.ComboThirdAttackingDashLeft, ctx => comboThirdBeforeWait.SelectedDashDir == ComboSelectDash.DashDir.Left);
            StateMachine.AddTransition(MaehwaStateId.ComboThirdAttackColliderActive, MaehwaStateId.ComboThirdAttackingDashRight, ctx => comboThirdBeforeWait.SelectedDashDir != ComboSelectDash.DashDir.Left);
            StateMachine.AddTransition(MaehwaStateId.ComboThirdAttackingDashLeft, MaehwaStateId.ComboAfterWait, _ => comboThirdLeftDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboThirdAttackingDashRight, MaehwaStateId.ComboAfterWait, _ => comboThirdRightDash.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.ComboAfterWait, MaehwaStateId.EndPhase, _ => comboThirdAfterWait.IsFinished);

            // === Rampage ===
            var rampageRise = new MoveLikeJump<MaehwaStateId>(MaehwaStateId.RampageRise, s.rampageRiseSpeed, s.rampageRiseTime);
            var rampageRiseWait = new WaitState<MaehwaStateId>(MaehwaStateId.RampageRiseWait, s.rampageRiseWaitTime, true);
            var rampageBeforeNoticeWait = new WaitState<MaehwaStateId>(MaehwaStateId.RampageBeforeNoticeWait, s.rampageBeforeNoticeWaitTime, true);
            var rampageBlink = new Teleport<MaehwaStateId>(MaehwaStateId.DownBlink, true, new Vector2(0, 7f), Context.PlayerTransform);
            var rampageNotice = new RampageAttackState(MaehwaStateId.RampageNotice, s.rampageNoticeInterval, s.rampageBeforeAttackTime, s.rampageAttackTime, s.rampageAttackAfterWaitTime);

            var rampageStart = new EmptyState<MaehwaStateId>(MaehwaStateId.RampageStart);
            StateMachine.AddState(MaehwaStateId.RampageStart, rampageStart);
            StateMachine.AddState(MaehwaStateId.RampageRise, rampageRise);
            StateMachine.AddState(MaehwaStateId.RampageRiseWait, rampageRiseWait);
            StateMachine.AddState(MaehwaStateId.RampageBeforeNoticeWait, rampageBeforeNoticeWait);
            StateMachine.AddState(MaehwaStateId.RampageBlink, rampageBlink);
            StateMachine.AddState(MaehwaStateId.RampageNotice, rampageNotice);

            StateMachine.AddTransition(MaehwaStateId.RampageStart, MaehwaStateId.RampageRise, _ => true);
            StateMachine.AddTransition(MaehwaStateId.RampageRise, MaehwaStateId.RampageRiseWait, _ => rampageRise.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.RampageRiseWait, MaehwaStateId.RampageBeforeNoticeWait, _ => rampageRiseWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.RampageBeforeNoticeWait, MaehwaStateId.RampageNotice, _ => rampageBeforeNoticeWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.RampageNotice, MaehwaStateId.DownAirWait, _ => true);

            // === Down ===
            var downBlink = new Teleport<MaehwaStateId>(MaehwaStateId.DownBlink, true, new Vector2(0, 7f), Context.PlayerTransform);
            var downAirWait = new WaitState<MaehwaStateId>(MaehwaStateId.DownAirWait, s.downAirWaitTime, true);
            var downGetAccel = new MoveByVelocity<MaehwaStateId>(MaehwaStateId.DownGetAccel, Vector2.down, s.downAccel, s.downAccelTime, 0f);
            var downSmashWait = new WaitState<MaehwaStateId>(MaehwaStateId.DownSmashWait, s.downAfterSmashTime, false);
            var downSmashRampageWait = new WaitState<MaehwaStateId>(MaehwaStateId.DownSmashRampageWait, s.rampageStaggerTime, false);

            var downStart = new EmptyState<MaehwaStateId>(MaehwaStateId.DownStart);
            StateMachine.AddState(MaehwaStateId.DownStart, downStart);
            StateMachine.AddState(MaehwaStateId.DownBlink, downBlink);
            StateMachine.AddState(MaehwaStateId.DownAirWait, downAirWait);
            StateMachine.AddState(MaehwaStateId.DownGetAccel, downGetAccel);
            StateMachine.AddState(MaehwaStateId.DownSmashWait, downSmashWait);
            StateMachine.AddState(MaehwaStateId.DownSmashRampageWait, downSmashRampageWait);

            StateMachine.AddTransition(MaehwaStateId.DownStart, MaehwaStateId.DownBlink, _ => true);
            StateMachine.AddTransition(MaehwaStateId.DownBlink, MaehwaStateId.DownAirWait, _ => true);
            StateMachine.AddTransition(MaehwaStateId.DownAirWait, MaehwaStateId.DownGetAccel, _ => downAirWait.IsFinished);
            StateMachine.AddTransition(MaehwaStateId.DownGetAccel, MaehwaStateId.DownSmashWait, ctx => ctx.IsOnPlatform());
            StateMachine.AddTransition(MaehwaStateId.DownSmashWait, MaehwaStateId.EndPhase, _ => true);
            StateMachine.AddTransition(MaehwaStateId.DownSmashRampageWait, MaehwaStateId.EndPhase, _ => true);

            // Select-Attack 에서 패턴 분기
            StateMachine.AddTransition(MaehwaStateId.SelectAttack, MaehwaStateId.ComboStart, _ => true);
            // StateMachine.AddTransition(MaehwaStateId.SelectAttack, MaehwaStateId.BodyStart, _ => true);
            // StateMachine.AddTransition(MaehwaStateId.SelectAttack, MaehwaStateId.HorizonStart, _ => true);
            // StateMachine.AddTransition(MaehwaStateId.SelectAttack, MaehwaStateId.RampageStart, _ => true);
            // StateMachine.AddTransition(MaehwaStateId.SelectAttack, MaehwaStateId.DownStart, _ => true);
        }
    }
}

using _Project.Features.Boss.Scripts;
using _Project.Features.Boss.Scripts.State;

namespace _Project.Features.Maehwa.Scripts.State
{
    public class ComboSelectDash : WaitState<MaehwaStateId>
    {
        private bool _isThird;
        public DashDir SelectedDashDir { get; private set; }
        public enum DashDir
        {
            None,
            Left,
            Right
        }

        public ComboSelectDash(MaehwaStateId id, float waitingSecond, bool notMoving = false, bool isThird = false) : base(id, waitingSecond, notMoving)
        {
            _isThird = isThird;
        }

        public override void OnEnter(BossContext<MaehwaStateId> ctx)
        {
            base.OnEnter(ctx);
            var c = ctx as MaehwaContext;
            if (!_isThird)
                SelectedDashDir = c? c.SelectDashDir() : DashDir.None;
            else
                SelectedDashDir = ctx.PlayerTransform.position.x < ctx.transform.position.x ? DashDir.Left : DashDir.Right;
        }
    }
}

using _Project.Features.Boss.Scripts;
using _Project.Features.Boss.Scripts.State;

namespace _Project.Features.Maehwa.Scripts.State
{
    public class ComboSelectDash : WaitState<MaehwaStateId>
    {
        private bool _isThird;
        public DashDir SelectedDashDir { get; private set; }
        public enum DashDir
        {
            None,
            Left,
            Right
        }
        
        public ComboSelectDash(MaehwaStateId id, float waitingSecond, bool notMoving = false, bool isThird = false) : base(id, waitingSecond, notMoving)
        {
            _isThird = isThird;
        }

        public override void OnEnter(BossContext<MaehwaStateId> ctx)
        {
            base.OnEnter(ctx);
            var c = ctx as MaehwaContext;
            if (!_isThird)
                SelectedDashDir = c? c.SelectDashDir() : DashDir.None;
            else
                SelectedDashDir = ctx.PlayerTransform.position.x < ctx.transform.position.x ? DashDir.Left : DashDir.Right;

            if (c != null)
                c.SelectedDashDir = SelectedDashDir;
        }
    }
}

using _Project.Features.Boss.Scripts;
using _Project.Features.Boss.Scripts.State;
using _Project.Features.Boss.Scripts.State.Moving;
using UnityEngine;

namespace _Project.Features.Maehwa.Scripts.State
{
    /// <summary>
    /// 매화 전용 콤보 공격 상태.
    /// 한 프레임 안에 콜라이더 활성(AttackFixedRange 역할)과 대시/대기를 함께 처리한다.
    /// </summary>
    public class MaehwaComboAttackState : BossState<MaehwaStateId, MaehwaContext>
    {
        private readonly MaehwaStateId _id;
        private readonly Vector2 _dashDir;
        private readonly float _dashSpeed;
        private readonly float _dashTime;
        private readonly float _noDashTime;
        private readonly BossAttackRangeType _attackType;

        private float _elapsed;
        private bool _colliderActivated;

        public enum BossAttackRangeType
        {
            None,
            ComboNormal,
            ComboSting
        }

        public MaehwaComboAttackState(
            MaehwaStateId id,
            Vector2 dashDir,
            float dashSpeed,
            float dashTime,
            float noDashTime,
            BossAttackRangeType attackType)
            : base(id)
        {
            _id = id;
            _dashDir = dashDir;
            _dashSpeed = dashSpeed;
            _dashTime = dashTime;
            _noDashTime = noDashTime;
            _attackType = attackType;
        }

        public override void OnEnter(MaehwaContext ctx)
        {
            IsFinished = false;
            _elapsed = 0f;
            _colliderActivated = false;

            ctx.NotifyStateEnter(ID);

            // 콜라이더 활성 (원래 AttackFixedRange 에서 하던 역할)
            var atk = ctx.Attack as MaehwaAttack;
            if (atk != null)
            {
                switch (_attackType)
                {
                    case BossAttackRangeType.ComboNormal:
                        if (atk.ComboNormalAttack != null)
                            atk.ComboNormalAttack.gameObject.SetActive(true);
                        break;
                    case BossAttackRangeType.ComboSting:
                        if (atk.ComboStingAttack != null)
                            atk.ComboStingAttack.gameObject.SetActive(true);
                        break;
                }
            }

            _colliderActivated = true;
        }

        public override void Tick(MaehwaContext ctx, float deltaTime)
        {
            if (IsFinished)
                return;

            _elapsed += deltaTime;

            // 대시 시간 혹은 노대시 시간 기준으로 종료
            float timeLimit = _dashDir == Vector2.zero ? _noDashTime : _dashTime;
            if (_elapsed >= timeLimit)
            {
                IsFinished = true;
            }
        }

        public override void FixedTick(MaehwaContext ctx, float deltaTime)
        {
            if (IsFinished)
            {
                ctx.StopMove();
                return;
            }

            // 대시 방향이 있으면 이동, 없으면 정지 상태 유지
            if (_dashDir != Vector2.zero)
            {
                ctx.Move(_dashDir.normalized * _dashSpeed);
            }
            else
            {
                ctx.StopMove();
            }
        }

        public override void OnExit(MaehwaContext ctx)
        {
            ctx.StopMove();
        }

        public override void HandleEvent(MaehwaContext ctx, object evt)
        {
        }
    }
}

using _Project.Features.Boss.Scripts;
using _Project.Features.Boss.Scripts.State;
using _Project.Features.Boss.Scripts.State.Moving;
using UnityEngine;

namespace _Project.Features.Maehwa.Scripts.State
{
    /// <summary>
    /// 매화 전용 콤보 공격 상태.
    /// 한 프레임 안에 콜라이더 활성(AttackFixedRange 역할)과 대시/대기를 함께 처리한다.
    /// </summary>
    public class MaehwaComboAttackState : BossState<MaehwaStateId, MaehwaContext>
    {
        private readonly Vector2 _baseDashDir;
        private readonly float _dashSpeed;
        private readonly float _dashTime;
        private readonly float _noDashTime;
        private readonly BossAttackRangeType _attackType;

        private float _elapsed;
        private bool _colliderActivated;
        private Vector2 _runtimeDashDir;

        public enum BossAttackRangeType
        {
            None,
            ComboNormal,
            ComboSting
        }

        public MaehwaComboAttackState(
            MaehwaStateId id,
            Vector2 dashDir,
            float dashSpeed,
            float dashTime,
            float noDashTime,
            BossAttackRangeType attackType)
            : base(id)
        {
            _baseDashDir = dashDir;
            _dashSpeed = dashSpeed;
            _dashTime = dashTime;
            _noDashTime = noDashTime;
            _attackType = attackType;
        }

        public override void OnEnter(MaehwaContext ctx)
        {
            IsFinished = false;
            _elapsed = 0f;
            _colliderActivated = false;

            ctx.NotifyStateEnter(ID);

            // ComboSelectDash 결과를 기반으로 실제 대시 방향 결정
            _runtimeDashDir = GetDashDirFromContext(ctx, _baseDashDir);

            // 콜라이더 활성 (원래 AttackFixedRange 에서 하던 역할)
            var atk = ctx.Attack as MaehwaAttack;
            if (atk != null)
            {
                switch (_attackType)
                {
                    case BossAttackRangeType.ComboNormal:
                        if (atk.ComboNormalAttack != null)
                            atk.ComboNormalAttack.gameObject.SetActive(true);
                        break;
                    case BossAttackRangeType.ComboSting:
                        if (atk.ComboStingAttack != null)
                            atk.ComboStingAttack.gameObject.SetActive(true);
                        break;
                }
            }

            _colliderActivated = true;
        }

        private Vector2 GetDashDirFromContext(MaehwaContext ctx, Vector2 fallback)
        {
            // MaehwaContext 안에 ComboSelectDash 결과가 저장되어 있다고 가정하고,
            // 없으면 생성자에서 넘겨준 기본 방향(fallback)을 사용.
            if (ctx.SelectedDashDir == ComboSelectDash.DashDir.Left)
                return Vector2.left;
            if (ctx.SelectedDashDir == ComboSelectDash.DashDir.Right)
                return Vector2.right;

            // Dash 없음이거나 아직 셋업이 안 됐으면 기본값 사용
            return fallback;
        }

        public override void Tick(MaehwaContext ctx, float deltaTime)
        {
            if (IsFinished)
                return;

            _elapsed += deltaTime;

            // 대시 시간 혹은 노대시 시간 기준으로 종료
            float timeLimit = _runtimeDashDir == Vector2.zero ? _noDashTime : _dashTime;
            if (_elapsed >= timeLimit)
            {
                IsFinished = true;
            }
        }

        public override void FixedTick(MaehwaContext ctx, float deltaTime)
        {
            if (IsFinished)
            {
                ctx.StopMove();
                return;
            }

            // 결정된 러untime 방향으로 이동
            if (_runtimeDashDir != Vector2.zero)
            {
                ctx.Move(_runtimeDashDir.normalized * _dashSpeed);
            }
            else
            {
                ctx.StopMove();
            }
        }

        public override void OnExit(MaehwaContext ctx)
        {
            ctx.StopMove();
        }

        public override void HandleEvent(MaehwaContext ctx, object evt)
        {
        }
    }
}
